CREATE OR REPLACE FUNCTION classify_filing_window(submission_date text, start_date text)
RETURNS text AS $$
DECLARE
    recv_d DATE;
    begin_d DATE;
    months_diff INTEGER;
BEGIN
    -- Parse the dates
    recv_d := CAST(submission_date AS DATE);
    begin_d := TO_DATE(start_date, 'DD/MM/YYYY');

    -- Calculate months difference (positive = start after submission, negative = start before submission)
    months_diff := EXTRACT(YEAR FROM AGE(begin_d, recv_d)) * 12 + 
                   EXTRACT(MONTH FROM AGE(begin_d, recv_d));

    -- Classify based on months difference
    IF months_diff < 0 THEN
        RETURN 'After Start Date';
    ELSIF months_diff = 0 AND EXTRACT(MONTH FROM begin_d) = EXTRACT(MONTH FROM recv_d) THEN
        RETURN 'Same Month';
    ELSIF months_diff BETWEEN 1 AND 3 THEN
        RETURN '1-3 Months Before';
    ELSIF months_diff BETWEEN 4 AND 6 THEN
        RETURN 'Optimal Window (4-6 Months)';
    ELSE
        RETURN 'Early Filing';
    END IF;
END;
$$ LANGUAGE plpgsql;

